import {worksheetHTML} from './worksheet.js';
import {completedProgress,createSyncQueue} from './classroom-sync.js';
import {SCENARIO,LESSON,RESIDENTS,STOP,BUS_STARTS} from './data.js';
import {evaluate,summary,time} from './engine.js';
import {connectBackend,createClass,readClass,watchClass,updateControl,joinClass,updateTeam,backendMode} from './classroom.js';

const app=document.querySelector('#app');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const phaseNames=LESSON.map(x=>x[0]);
const route=()=>location.hash.replace(/^#\/?/,'').split('?')[0].split('/').filter(Boolean);
let dispose=()=>{},dashboardTimer,latestClass,currentCode,qrOpen=false,detailTeam=null,endOpen=false,busy=false;

function shell(content,kind=''){document.body.className=kind;app.innerHTML=content;bindCommon();}
function logo(){return `<div class="portal-brand"><span class="portal-bus"><svg viewBox="0 0 32 40" aria-hidden="true"><rect x="3" y="1" width="26" height="34" rx="7" fill="currentColor"/><rect x="7" y="9" width="18" height="13" rx="2" fill="white"/><path d="M11 5h10" stroke="white" stroke-width="2" stroke-linecap="round"/><circle cx="9" cy="28" r="2" fill="white"/><circle cx="23" cy="28" r="2" fill="white"/><path d="M7 33v4m18-4v4" stroke="currentColor" stroke-width="5" stroke-linecap="round"/></svg></span><div><b>이 버스는 누구를 지나치는가</b><small>고등학교 통합사회 · 노선 설계 활동</small></div></div>`;}
function notice(text,type=''){return `<p class="portal-notice ${type}">${esc(text)}</p>`;}
function setNotice(text,type=''){const el=document.querySelector('#portal-notice');if(el){el.className=`portal-notice ${type}`;el.textContent=text;}}
function bindCommon(){document.querySelectorAll('[data-nav]').forEach(el=>el.addEventListener('click',()=>{location.hash=el.dataset.nav;}));}

function renderLanding(){dispose();clearInterval(dashboardTimer);shell(`<main class="welcome-page">
 <section class="welcome" aria-labelledby="welcome-title">
  <div class="welcome-copy">
   <p class="welcome-subject"><svg viewBox="0 0 32 40" aria-hidden="true"><rect x="3" y="1" width="26" height="34" rx="7" fill="currentColor"/><rect x="7" y="9" width="18" height="13" rx="2" fill="white"/><path d="M11 5h10" stroke="white" stroke-width="2" stroke-linecap="round"/><circle cx="9" cy="28" r="2" fill="white"/><circle cx="23" cy="28" r="2" fill="white"/><path d="M7 33v4m18-4v4" stroke="currentColor" stroke-width="5" stroke-linecap="round"/></svg><span>고등학교 통합사회</span></p>
   <div class="welcome-heading"><p class="welcome-eyebrow">노선 설계 활동</p><h1 id="welcome-title">이 버스는<br>누구를<br><span>지나치는가</span></h1></div>
   <div class="welcome-launch"><button id="create-class" class="welcome-start"><span>새 수업 만들기</span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 12h15m-6-6 6 6-6 6"/></svg></button><div class="welcome-links"><a href="#guide">수업 안내</a><a href="#play" target="_blank" rel="noopener">활동 미리보기 <span aria-hidden="true">↗</span></a></div><p id="portal-notice" class="portal-notice" role="status"></p></div>
   <svg class="welcome-tracks" viewBox="0 0 550 210" fill="none" aria-hidden="true"><path d="M-30 170h235c85 0 55-120 145-120h240" stroke="#1762ee"/><path d="M-30 195h244c87 0 66-120 144-120h220" stroke="#f79443"/><circle cx="132" cy="170" r="8"/><circle cx="443" cy="50" r="8"/></svg>
  </div>
  <div class="welcome-city" role="img" aria-label="강과 다리로 연결된 언덕마을, 아파트, 학교, 마을 버스터미널, 병원과 공장 지도">
   <div class="welcome-scene"><img src="./assets/town-map.png" alt="" fetchpriority="high">
   <span class="welcome-place hill">언덕마을<i></i></span><span class="welcome-place school">학교<i></i></span><span class="welcome-place hospital">병원<i></i></span><span class="welcome-place apartments">아파트<i></i></span><span class="welcome-place center">마을 버스터미널<i></i></span><span class="welcome-place factory">공장<i></i></span>
   </div><div class="welcome-map-caption" aria-hidden="true"><span class="welcome-route blue">1호차</span><span class="welcome-route orange">2호차</span><span>우리 모둠이 연결할 마을</span></div>
  </div>
 </section></main>`,'portal-mode');
 $('#create-class').addEventListener('click',async()=>{if(busy)return;busy=true;const b=$('#create-class');b.disabled=true;b.textContent='수업 여는 중…';try{const klass=await createClass();sessionStorage.setItem('bus-auto-qr',klass.code);location.hash=`teacher/${klass.code}`;}catch(e){setNotice(firebaseMessage(e),'error');b.disabled=false;b.textContent='새 수업 만들기';busy=false;}});
}
const $=s=>document.querySelector(s);
function firebaseMessage(e){const raw=String(e?.message||e);if(raw.includes('auth/operation-not-allowed'))return 'Firebase에서 익명 로그인을 켜야 수업을 만들 수 있습니다.';if(raw.includes('PERMISSION_DENIED'))return 'Firebase 데이터베이스 규칙을 확인해 주세요.';if(raw.includes('configuration-not-found'))return 'Firebase Authentication을 먼저 시작해 주세요.';return raw.replace(/^Firebase:\s*/,'');}

function renderTeacherGuide(){dispose();clearInterval(dashboardTimer);shell(`<main class="teacher-guide-page"><header class="guide-top">${logo()}<a class="portal-ghost" href="#">처음으로</a></header><section class="guide-intro"><p class="portal-kicker">교사를 위한 수업 안내</p><h1>두 대의 버스, 서로 다른 여덟 번의 아침.</h1><p>주민의 사정을 읽고, 노선을 설계하고, 이동 결과를 근거로 다시 선택합니다.<br>학생의 선택을 먼저 경험한 뒤 통합사회의 개념으로 연결하는 45분 활동입니다.</p><div class="guide-meta"><span>고등학교 통합사회</span><span>2인 1조</span><span>아이패드 가로 화면</span><span>45분</span></div></section><div class="guide-columns"><section class="guide-section"><h2>수업 전, 세 가지만 준비하세요</h2><ol class="guide-prep"><li><b>주민 정보표와 활동지 한 세트</b><p>모둠당 A4 단면 2쪽을 인쇄해 나란히 펼쳐 주세요. 주민 조건을 보며 활동지 한 장에 함께 기록합니다. 종이로 작성하면 앱에 다시 입력할 필요는 없으며, 종이 답변은 대시보드 성찰 수에 집계되지 않습니다.</p><a href="#/print/residents" target="_blank" rel="noopener">인쇄 자료 열기 →</a></li><li><b>교사 미리보기로 한 번 운행</b><p>정류장 추가, 출발 시각, 저상버스 배치를 바꿔 보세요. 연습 내용은 학생 수업에 전송되지 않습니다.</p><a href="#play" target="_blank" rel="noopener">활동 미리보기 →</a></li><li><b>새 수업을 만들고 QR 표시</b><p>모둠마다 기기 한 대로 입장합니다. 모두 들어오면 대시보드에서 ‘수업 시작’을 누르세요.</p></li></ol><div class="guide-note">수업을 만든 <b>같은 기기·같은 브라우저</b>에서 대시보드를 운영해 주세요. 브라우저 데이터를 지우면 기존 수업의 교사 권한을 복구할 수 없습니다.</div></section><section class="guide-section"><h2>45분 수업 흐름</h2><ol class="guide-phases">${LESSON.map(([name,min],i)=>`<li><span class="guide-phase-number">${i+1}</span><div><b>${name}</b><p>${['주민 한 명의 하루에서 시작합니다.','한 명은 조작, 한 명은 주민 조건을 확인합니다.','이동 불가·지각의 이유를 기록합니다.','두 학생이 놓친 주민의 입장에서 논의합니다.','역할을 바꾸고 첫 설계를 수정합니다.','새로 이동 가능한 사람과 더 걸리는 사람을 비교합니다.','활동지의 선택 이유와 주민 사례를 나누고 개념으로 연결합니다.'][i]}</p></div><small>${min}분</small></li>`).join('')}</ol></section></div><section class="guide-conclusion"><h2>모두의 이동을 연결하고, 지각을 줄여 봅니다.</h2><p>먼저 8명 모두의 이동을 연결하고, 그 안에서 지각하는 사람과 지각 시간을 줄이게 해 주세요. 누구의 이동이 좋아졌고 누구의 기다림이 늘었는지, 그 선택의 이유를 설명하게 합니다. 그 결과에서 <b>공간 불평등, 실질적인 기회, 공공서비스 분배</b>를 연결합니다. 모든 주민을 개선했다면 그 결과를 그대로 인정합니다.</p><p class="guide-assumption">교육용 가상 도시·주민 자료입니다. 혼잡과 정원 제한은 생략하며, 노선·시각·보행 조건·저상버스 배치에 따라 결과가 계산됩니다.</p></section><a class="portal-primary guide-start" href="#">수업 만들러 가기 →</a></main>`,'portal-mode');}

function renderCodeEntry(){shell(`<main class="join-page"><header class="join-head">${logo()}</header><form class="join-form solo" id="code-form"><p class="portal-kicker">학생용 입장</p><h1>수업 코드 입력</h1><p>선생님 화면에 표시된 6자리 숫자를 입력하세요.</p><label class="sr-only" for="class-code">수업 코드</label><input id="class-code" inputmode="numeric" autocomplete="off" pattern="[0-9]{6}" maxlength="6" required placeholder="6자리 수업 코드"><button class="portal-primary" type="submit">이 수업에 입장하기</button></form></main>`,'portal-mode');$('#code-form').addEventListener('submit',event=>{event.preventDefault();const code=$('#class-code').value.trim();if(/^\d{6}$/.test(code))location.hash=`join/${code}`;});}
async function renderJoin(code){dispose();clearInterval(dashboardTimer);shell(`<main class="join-page"><header class="join-head">${logo()}<button class="portal-ghost" data-nav="">처음으로</button></header><section class="join-card"><div class="join-art"><img src="./assets/town-map.png" alt="강과 다리로 이어진 활동 속 가상 도시"><span>수업 코드 <b>${esc(code)}</b></span></div><div class="join-form"><p class="portal-kicker">학생용 입장</p><h1>우리 모둠으로 참여하기</h1><p>모둠 이름은 선생님 화면에서 진행 상황을 구분하는 데 사용됩니다.</p><label for="team-name">모둠 이름</label><input id="team-name" maxlength="24" autocomplete="off" placeholder="예: 다리놓는사람들"><button class="portal-primary" id="join-team" disabled>수업 확인 중…</button><p id="portal-notice" class="portal-notice">수업을 확인하고 있어요.</p></div></section></main>`,'portal-mode');
 try{const klass=await readClass(code);if(!klass){setNotice('수업 코드를 찾을 수 없습니다. 선생님 화면의 코드를 확인해 주세요.','error');$('#join-team').disabled=true;return;}if(klass.control?.status==='ended'){setNotice('이미 종료된 수업입니다.','error');$('#join-team').disabled=true;return;}const savedId=localStorage.getItem(`bus-team-${code}`);if(savedId&&klass.teams?.[savedId]){await startStudent(code,klass.teams[savedId],klass);return;}setNotice(klass.control?.status==='lobby'?'입장하면 선생님이 수업을 시작할 때까지 기다립니다.':`${phaseNames[klass.control?.phase||0]} 단계가 진행 중입니다.`);$('#team-name').focus();$('#join-team').disabled=false;$('#join-team').textContent='수업에 입장하기';}catch(e){setNotice(firebaseMessage(e),'error');return;}
 $('#join-team')?.addEventListener('click',async()=>{const name=$('#team-name').value.trim();if(!name){setNotice('모둠 이름을 입력해 주세요.','error');return;}const b=$('#join-team');b.disabled=true;b.textContent='입장 중…';try{const team=await joinClass(code,name);const klass=await readClass(code);await startStudent(code,team,klass);}catch(e){setNotice(firebaseMessage(e),'error');b.disabled=false;b.textContent='수업에 입장하기';}});
}
async function startStudent(code,team,klass){
 dispose();clearInterval(dashboardTimer);
 const storageKey=`bus-neighbors-v2-${code}-${team.uid}`;
 if(team.studentState&&!localStorage.getItem(storageKey))localStorage.setItem(storageKey,JSON.stringify(team.studentState));
 const queue=createSyncQueue(payload=>updateTeam(code,team.uid,{studentState:payload.state,progress:{...completedProgress(payload.state,payload.mode),updatedAt:Date.now()}}),ok=>window.dispatchEvent(new CustomEvent('classroom-sync-status',{detail:ok})));
 window.BUS_CLASSROOM={code,teamId:team.uid,teamName:team.name,control:klass.control,storageKey,backend:backendMode(),sync:queue.enqueue};
 const retry=()=>queue.flush();window.addEventListener('online',retry);
 let roomKey=JSON.stringify([klass.control,team.name]);
 document.body.className='student-class-mode';app.innerHTML='<div class="portal-loading">마을 지도를 불러오는 중…</div>';
 const stop=watchClass(code,(value,error)=>{
  const control=error||!value?{status:'paused',phase:0,message:'수업 연결을 확인하고 있습니다. 입력한 내용은 이 기기에 보관됩니다.'}:value.control;
  const name=value?.teams?.[team.uid]?.name||team.name,key=JSON.stringify([control,name]);
  if(key===roomKey)return;
  roomKey=key;window.BUS_CLASSROOM.control=control;window.BUS_CLASSROOM.teamName=name;
  window.dispatchEvent(new CustomEvent('classroom-state'));
 });
 dispose=()=>{stop();window.removeEventListener('online',retry);};
 await import('./app.js');
}
async function startPreview(code){const klass=await readClass(code);if(!klass){renderNotFound();return;}window.BUS_CLASSROOM={code,teamId:'preview',teamName:'교사 리허설',control:{...klass.control,status:'active'},storageKey:`bus-preview-${code}`,backend:'preview',preview:true,sync(){}};document.body.className='student-class-mode';app.innerHTML='';await import('./app.js');}

function teacherHeader(k){return `<header class="teacher-header"><button class="portal-ghost" data-nav="">← 처음으로</button>${logo()}<div class="teacher-head-actions"><button class="class-code-button" data-action="qr"><small>수업 코드</small><b>${k.code}</b></button><button class="portal-ghost" data-action="print">자료 인쇄</button><button class="portal-ghost" data-action="preview">학생 화면 미리보기</button><button class="portal-ghost" data-action="qr">학생 입장 QR</button><button class="portal-ghost danger" data-action="${k.control.status==='ended'?'reopen':'end'}">${k.control.status==='ended'?'수업 다시 열기':'수업 종료'}</button></div></header>`;}
function remaining(k){const c=k.control;if(c.status==='lobby')return c.phaseDuration*60;if(c.status==='ended')return 0;const anchor=c.status==='paused'?(c.pausedAt||Date.now()):Date.now();return Math.max(0,c.phaseDuration*60-Math.floor((anchor-(c.phaseStartedAt||anchor))/1000));}
function timeDisplay(sec){return `${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`;}
function teamProgress(team){const mode=team.progress?.mode||'waiting';return completedProgress(team.studentState||{attempts:[],reflections:[]},mode);}
function dashboardBody(k){const teams=Object.values(k.teams||{}).sort((a,b)=>a.joinedAt-b.joinedAt),submitted=teams.filter(t=>teamProgress(t).attempts>0).length,revised=teams.filter(t=>teamProgress(t).attempts>1).length,reflected=teams.filter(t=>teamProgress(t).reflectionDone===3).length,sec=remaining(k),phase=k.control.phase||0;
 const missed=RESIDENTS.map((p,i)=>({name:p.name,count:teams.filter(t=>teamProgress(t).results?.[i]?.status==='impossible').length,late:teams.filter(t=>teamProgress(t).results?.[i]?.status==='late').length})).sort((a,b)=>b.count-a.count||b.late-a.late).slice(0,5);
 return `<main class="teacher-main"><section class="stage-strip" aria-label="45분 수업 단계">${LESSON.map(([name,min],i)=>`<button class="stage-pill ${i===phase?'active':''} ${i<phase?'done':''}" data-action="phase" data-phase="${i}"><i>${i+1}</i><span>${name}<small>${min}분</small></span></button>`).join('')}</section><section class="dashboard-grid"><div class="dashboard-left"><article class="control-card"><div class="control-title"><div><p class="portal-kicker">현재 진행</p><h1>${phase+1}. ${phaseNames[phase]}</h1><p>${esc(k.control.message||stagePrompt(phase))}</p></div><div class="timer ${sec<60&&k.control.status==='active'?'urgent':''}"><small>${k.control.status==='paused'?'일시정지':k.control.status==='lobby'?'입장 대기':k.control.status==='ended'?'수업 종료':'남은 시간'}</small><strong id="teacher-timer">${timeDisplay(sec)}</strong></div></div><div class="control-actions">${k.control.status==='lobby'?`<button class="portal-primary" data-action="start">수업 시작</button>`:k.control.status==='ended'?`<button class="portal-primary" data-action="reopen">현재 단계에서 다시 열기</button>`:`<button class="portal-primary" data-action="pause">${k.control.status==='paused'?'계속 진행':'일시정지'}</button><button class="portal-ghost" data-action="extend">+ 1분</button><button class="portal-ghost" data-action="restart-timer">타이머 다시 시작</button><button class="portal-ghost" data-action="next" ${phase===6?'disabled':''}>다음 단계 →</button>`}</div><div class="broadcast"><label for="broadcast">학생 화면 안내 문구</label><input id="broadcast" maxlength="90" value="${esc(k.control.message||'')}" placeholder="예: 지각한 주민 한 명의 경로를 다시 살펴보세요."><button class="portal-ghost" data-action="broadcast">보내기</button></div></article><article class="teams-card"><div class="card-head"><div><p class="portal-kicker">실시간 모둠 현황</p><h2>입장한 모둠 ${teams.length}개</h2></div><button class="portal-ghost class-export" data-action="export" ${teams.length?'':'disabled'}>결과 내려받기</button><div class="mini-stats"><span>첫 결과 <b>${submitted}/${teams.length}</b></span><span>재설계 <b>${revised}/${teams.length}</b></span><span>성찰 완료 <b>${reflected}/${teams.length}</b></span></div></div>${teams.length?`<div class="team-table"><div class="team-row header"><span>모둠</span><span>현재 화면</span><span>시도</span><span>최근 결과<small>정시 · 지각 · 불가</small></span><span>성찰</span></div>${teams.map(t=>{const p=teamProgress(t),s=p.summary||{};return `<button class="team-row" data-action="team" data-team="${esc(t.uid)}"><span><b>${esc(t.name)}</b><small>${activeAgo(t.lastSeen)}</small></span><span>${modeLabel(p.mode)}</span><span>${p.attempts||0}회</span><span class="result-inline">${!p.attempts?'<small>아직 운행 전</small>':`<i class="ok" aria-label="정시 ${s.ontime||0}명">${s.ontime||0}</i><i class="late" aria-label="지각 ${s.late||0}명">${s.late||0}</i><i class="no" aria-label="이동 불가 ${s.impossible||0}명">${s.impossible||0}</i>`}</span><span>${p.reflectionDone||0}/3</span></button>`;}).join('')}</div>`:'<div class="empty-teams"><span class="empty-people" aria-hidden="true"><svg viewBox="0 0 40 40" fill="none" stroke="currentColor" stroke-width="1.7"><circle cx="15" cy="13" r="5"/><path d="M5 31v-3a10 10 0 0 1 20 0v3M26 9a5 5 0 0 1 0 10m3 4a9 9 0 0 1 6 8" stroke-linecap="round"/></svg></span><h3>학생 모둠을 기다리고 있어요.</h3><p>학생 QR을 화면에 띄우거나 링크를 공유하세요.</p><button class="portal-primary" data-action="qr">학생 입장 QR 보기</button></div>'}</article></div><aside class="dashboard-side"><article class="side-card"><p class="portal-kicker">현재 주민별 결과</p><h3>많이 놓친 주민</h3>${teams.some(t=>teamProgress(t).results)?`<div class="missed-list">${missed.map(x=>`<div><b>${x.name}</b><span>이동 불가 ${x.count} · 지각 ${x.late}</span><i style="--w:${submitted?(x.count+x.late)/submitted*100:0}%"></i></div>`).join('')}</div>`:'<p class="side-empty">모둠이 첫 운행을 마치면 주민별 결과가 나타납니다.</p>'}</article><article class="side-card lesson-tip"><p class="portal-kicker">교사 질문</p><p>${teacherQuestion(phase)}</p></article></aside></section></main>`;}
function stagePrompt(i){return ['인쇄 자료에서 주민의 출발·도착·보행 조건을 확인하세요.','고정 기점에서 이어지는 두 노선과 저상버스 배치를 결정하세요.','첫 노선을 운행하고 주민별 결과를 저장하세요.','지각하거나 이동할 수 없는 주민의 이유를 찾으세요.','같은 도시 조건에서 노선을 다시 설계하세요.','첫 시도와 수정 시도의 변화를 비교하세요.','세 질문에 모둠의 생각을 기록하세요.'][i];}
function teacherQuestion(i){return ['출발 시각과 보행 조건이 서로 다른 주민은 누구인가요?','이 노선에서 가장 오래 기다릴 사람은 누구일까요?','예상과 실제 결과가 달랐던 주민은 누구인가요?','정류장은 있는데 이동하지 못한 주민이 있나요?','새 연결로 왕복 시간이 얼마나 늘었나요?','새로 이동 가능해진 사람과 더 오래 걸린 사람은 누구인가요?','정류장의 존재와 실질적인 이동 기회는 어떻게 다른가요?'][i];}
function activeAgo(t){if(!t)return '접속 기록 없음';const d=Math.max(0,Math.floor((Date.now()-t)/1000));return d<20?'지금 접속':d<60?`${d}초 전`:d<3600?`${Math.floor(d/60)}분 전`:'오래 전';}
function modeLabel(m){return ({waiting:'입장 대기',design:'노선 설계',run:'운행 중',results:'결과 비교',reflection:'생각 정리',paused:'수업 일시정지',ended:'수업 종료'}[m]||'활동 중');}
function qrModal(k){const link=`${location.origin}${location.pathname}#/join/${k.code}`,entry=`${location.origin}${location.pathname}#join`,src=`https://api.qrserver.com/v1/create-qr-code/?size=420x420&margin=14&data=${encodeURIComponent(link)}`;return `<div class="portal-modal-shade"><section class="qr-modal" role="dialog" aria-modal="true" aria-labelledby="qr-title"><button class="modal-x" data-action="close-modal" aria-label="닫기">×</button><header class="qr-heading"><p class="portal-kicker">우리 반 수업에 참여하기</p><h2 id="qr-title">학생 입장 QR</h2><p>아이패드 카메라로 스캔한 뒤 모둠 이름을 입력하세요.</p></header><div class="qr-content"><img src="${src}" alt="수업 코드 ${k.code} 학생 입장 QR 코드"><div class="qr-access"><div class="big-code"><small>수업 코드</small><b>${k.code}</b></div><div class="access-address"><small>QR 인식이 어려우면 아래 주소로 접속</small><strong>${esc(entry)}</strong><small>접속 후 위의 6자리 수업 코드를 입력하세요.</small></div><button class="copy-address" data-action="copy-link">접속 주소 복사</button><p class="qr-pair-note">2인 1조 · 모둠당 기기 한 대</p></div></div></section></div>`;}
function resultLabel(r){return !r||r.arrival==null?'이동 불가':`${time(r.arrival)} · ${r.status==='late'?'지각':'정시'} · ${r.duration}분`;}
function teacherChange(first,last){if(first.arrival==null)return last.arrival==null?'여전히 이동 불가':'새롭게 이동 가능';if(last.arrival==null)return '이동 가능 → 불가';const diff=last.duration-first.duration;return diff>0?`${diff}분 더 걸림`:diff<0?`${-diff}분 줄어듦`:'이동 시간 같음';}
function teamModal(k,id){
 const t=k.teams?.[id];if(!t)return '';
 const p=teamProgress(t),attempts=(t.studentState?.attempts||[]).filter(a=>a.scenario===SCENARIO.id),first=attempts[0],last=attempts.at(-1),answers=t.studentState?.scenario===SCENARIO.id?t.studentState.reflections||[]:[];
 return `<div class="portal-modal-shade"><section class="team-modal" role="dialog" aria-modal="true" aria-labelledby="team-title"><button class="modal-x" data-action="close-modal" aria-label="닫기">×</button><p class="portal-kicker">모둠 상세</p><h2 id="team-title">${esc(t.name)}</h2><div class="team-metrics"><span>시도 <b>${p.attempts}회</b></span><span>성찰 <b>${p.reflectionDone}/3</b></span></div>
 ${last?`<h3>${attempts.length>1?'첫 시도와 최근 시도 비교':'첫 운행 결과'}</h3><div class="table-wrap"><table class="teacher-comparison"><thead><tr><th>주민</th>${attempts.length>1?'<th>첫 시도</th>':''}<th>최근 결과</th>${attempts.length>1?'<th>변화</th>':''}</tr></thead><tbody>${RESIDENTS.map((person,i)=>`<tr><th>${person.name}</th>${attempts.length>1?`<td>${resultLabel(first.results[i])}</td>`:''}<td>${resultLabel(last.results[i])}</td>${attempts.length>1?`<td>${teacherChange(first.results[i],last.results[i])}</td>`:''}</tr>`).join('')}</tbody></table></div>`: '<p class="side-empty">아직 저장된 운행 결과가 없습니다.</p>'}
 <section class="teacher-reflections"><h3>모둠의 생각</h3>${['우리의 선택으로 이동이 가능해진 사람은 누구인가?','그 대신 누가 더 기다리거나 돌아가게 되었는가?','정류장이 있다는 것과 실제로 목적지에 갈 수 있다는 것은 어떻게 다른가?'].map((q,i)=>`<article><h4>${i+1}. ${q}</h4><p>${esc(answers[i]?.trim()||'아직 작성하지 않았습니다.')}</p></article>`).join('')}</section><button class="portal-primary modal-done" data-action="close-modal">확인</button></section></div>`;
}
function renderPrint(){dispose();clearInterval(dashboardTimer);const cards=RESIDENTS.map((p,i)=>`<article class="print-resident"><header><b>${i+1}. ${esc(p.name)}</b><span>${esc(p.role)}${p.low?' · 저상버스 필요':''}</span></header><p class="print-story">${esc(p.story)}</p><dl><dt>이동</dt><dd>${esc(p.home)} → ${esc(p.destination)}</dd><dt>시간</dt><dd>${time(p.ready)}부터 출발 · ${time(p.deadline)}까지 도착</dd><dt>집 → 정류장</dt><dd>${Object.entries(p.access).map(([id,m])=>`${STOP[id].name} ${m}분`).join(' · ')}</dd><dt>하차 후</dt><dd>${Object.entries(p.egress).map(([id,m])=>`${STOP[id].name} 정류장 → ${p.destination} ${m}분`).join(' · ')}</dd><dt>보행</dt><dd>${esc(p.walk)}</dd></dl></article>`).join('');shell(`<div class="print-toolbar"><div><h2>주민 정보표 + 모둠 활동지</h2><p>모둠당 1세트 · A4 단면 2쪽 · 배율 100% 권장<br>두 장을 나란히 놓고 함께 작성하세요. 활동지로 기록할 때는 앱의 성찰 입력을 생략해도 됩니다.</p></div><div class="print-actions"><button class="portal-ghost" data-nav="">처음으로</button><button class="portal-primary" id="print-now">2쪽 인쇄하기</button></div></div><main class="print-pack"><section class="print-sheet" aria-label="주민 정보표"><header class="print-sheet-head"><div><p>고등학교 통합사회 · 교육용 가상 자료</p><h1>이 버스는 누구를 지나치는가</h1><span>주민 이동 조건표 · 오전 07:00–10:00</span></div><b class="sheet-number">01 / 주민 정보표</b></header><section class="print-rule"><b>운영 조건</b><span>1호차는 ${STOP[BUS_STARTS[0]].name} 출발 · 2호차는 ${STOP[BUS_STARTS[1]].name} 출발 · 저상버스는 1대 · 환승 최대 1회</span></section><section class="print-grid">${cards}</section><footer>정류장이 있어도 출발 시각, 보행 조건, 노선, 차량 종류가 맞아야 실제로 목적지에 갈 수 있습니다.</footer></section>${worksheetHTML()}</main>`,'print-mode');const printWhenReady=async()=>{await document.fonts.ready;window.print();};$('#print-now').addEventListener('click',printWhenReady);if(location.hash.includes('auto=1'))setTimeout(printWhenReady,350);}
function renderTeacher(k){
 const previous=latestClass,focused=document.activeElement,broadcast=$('#broadcast');
 const draft=broadcast&&broadcast.value!==(previous?.control.message||'')?broadcast.value:null;
 const selection=focused===broadcast?[broadcast.selectionStart,broadcast.selectionEnd]:null;
 const modalScroll=$('.team-modal')?.scrollTop||0;
 const patchOnly=document.body.classList.contains('teacher-mode')&&$('.teacher-main')&&previous?.code===k.code&&JSON.stringify(previous.control)===JSON.stringify(k.control);
 latestClass=k;
 if(patchOnly){
  const fragment=document.createElement('div');fragment.innerHTML=dashboardBody(k);
  $('.teams-card').replaceWith(fragment.querySelector('.teams-card'));
  $('.dashboard-side').replaceWith(fragment.querySelector('.dashboard-side'));
 }else{
  shell(`${teacherHeader(k)}${dashboardBody(k)}`,'teacher-mode');
  if(draft!==null)$('#broadcast').value=draft;
  if(selection){$('#broadcast').focus({preventScroll:true});$('#broadcast').setSelectionRange(...selection);}
 }
 // Keep the QR image and focused controls intact while other groups save.
 const existing=$('.portal-modal-shade');
 if(!qrOpen||!existing||!existing.querySelector('.qr-modal')){
  existing?.remove();
  const modal=endOpen?endModal(k):qrOpen?qrModal(k):detailTeam?teamModal(k,detailTeam):'';
  if(modal)app.insertAdjacentHTML('beforeend',modal);
 }
 if($('.team-modal'))$('.team-modal').scrollTop=modalScroll;
 bindTeacher(k);
 document.querySelectorAll('[data-action="print"]').forEach(el=>el.onclick=()=>window.open(`${location.origin}${location.pathname}#/print/residents?auto=1`,'_blank','noopener'));
 clearInterval(dashboardTimer);dashboardTimer=setInterval(()=>{const el=$('#teacher-timer');if(el)el.textContent=timeDisplay(remaining(latestClass));},1000);
}
async function mountTeacher(code){dispose();clearInterval(dashboardTimer);currentCode=code;shell(`<div class="portal-loading">교사용 대시보드를 불러오는 중…</div>`,'teacher-mode');try{const {uid}=await connectBackend();const klass=await readClass(code);if(!klass){renderNotFound();return;}if(klass.teacherUid!==uid){shell(`<main class="join-page"><section class="join-form solo"><p class="portal-kicker">교사용 입장</p><h1>이 브라우저에서 만든 수업이 아닙니다.</h1><p>수업을 만든 교사 기기에서 대시보드를 열어 주세요.</p><button class="portal-ghost" data-nav="">처음으로</button></section></main>`,'portal-mode');return;}if(sessionStorage.getItem('bus-auto-qr')===code){qrOpen=true;sessionStorage.removeItem('bus-auto-qr');}dispose=watchClass(code,(value,error)=>{if(error){shell(`<div class="portal-loading error">${esc(firebaseMessage(error))}</div>`,'teacher-mode');return;}if(value)renderTeacher(value);});}catch(e){shell(`<div class="portal-loading error">${esc(firebaseMessage(e))}<button class="portal-primary" data-nav="">처음으로</button></div>`,'teacher-mode');}}
function bindTeacher(k){document.querySelectorAll('[data-action]').forEach(el=>el.onclick=async()=>{const action=el.dataset.action;try{if(action==='qr'){endOpen=false;qrOpen=true;detailTeam=null;renderTeacher(k);}if(action==='close-modal'){endOpen=false;qrOpen=false;detailTeam=null;renderTeacher(k);}if(action==='copy-link'){await navigator.clipboard.writeText(`${location.origin}${location.pathname}#join`);el.textContent='복사됨';}if(action==='preview')window.open(`${location.origin}${location.pathname}#/preview/${k.code}`,'_blank','noopener');if(action==='start')await updateControl(k.code,{status:'active',phaseStartedAt:'SERVER_TIME',pausedAt:0,message:stagePrompt(k.control.phase||0)});if(action==='pause'){if(k.control.status==='paused'){const elapsed=(k.control.pausedAt||Date.now())-(k.control.phaseStartedAt||Date.now());await updateControl(k.code,{status:'active',phaseStartedAt:Date.now()-elapsed,pausedAt:0});}else await updateControl(k.code,{status:'paused',pausedAt:Date.now()});}if(action==='extend')await updateControl(k.code,{phaseDuration:(k.control.phaseDuration||LESSON[k.control.phase][1])+1});if(action==='restart-timer')await updateControl(k.code,{phaseStartedAt:'SERVER_TIME',pausedAt:0,status:'active'});if(action==='next'){const phase=Math.min(6,(k.control.phase||0)+1);await updateControl(k.code,{phase,phaseDuration:LESSON[phase][1],phaseStartedAt:'SERVER_TIME',pausedAt:0,status:'active',message:stagePrompt(phase)});}if(action==='phase'){const phase=Number(el.dataset.phase);await updateControl(k.code,{phase,phaseDuration:LESSON[phase][1],phaseStartedAt:'SERVER_TIME',pausedAt:0,status:k.control.status==='lobby'?'lobby':'active',message:stagePrompt(phase)});}if(action==='broadcast'){const message=$('#broadcast').value.trim();await updateControl(k.code,{message});}if(action==='end'){endOpen=true;qrOpen=false;detailTeam=null;renderTeacher(k);}if(action==='confirm-end'){await updateControl(k.code,{status:'ended',pausedAt:Date.now()});endOpen=false;renderTeacher(latestClass);}if(action==='reopen')await updateControl(k.code,{status:'active',phaseStartedAt:'SERVER_TIME',pausedAt:0});if(action==='team'){endOpen=false;detailTeam=el.dataset.team;qrOpen=false;renderTeacher(k);}if(action==='export')exportClass(k);}catch(e){alert(firebaseMessage(e));}});}
function endModal(k){const teams=Object.values(k.teams||{}),done=teams.filter(t=>teamProgress(t).reflectionDone===3).length,revised=teams.filter(t=>teamProgress(t).attempts>=2).length;return `<div class="portal-modal-shade"><section class="team-modal end-modal" role="dialog" aria-modal="true" aria-labelledby="end-title"><button class="modal-x" data-action="close-modal" aria-label="닫기">×</button><p class="portal-kicker">수업 마무리</p><h2 id="end-title">모둠의 기록을 확인하세요</h2><div class="end-progress"><p><span>재설계 결과 도착</span><b>${revised} / ${teams.length} 모둠</b></p><p><span>성찰 세 문항 작성</span><b>${done} / ${teams.length} 모둠</b></p></div><p class="end-copy">${teams.length-done?`아직 ${teams.length-done}개 모둠의 성찰이 모두 도착하지 않았습니다. `:''}종료하면 학생 화면의 편집이 멈춥니다. 기록은 대시보드에 남고, 필요하면 수업을 다시 열 수 있습니다.</p><div class="end-actions"><button class="portal-ghost" data-action="close-modal">수업 계속하기</button><button class="portal-primary" data-action="confirm-end">수업 종료하기</button></div></section></div>`;}
function exportClass(k){const blob=new Blob([JSON.stringify({exportedAt:new Date().toISOString(),classCode:k.code,control:k.control,teams:Object.values(k.teams||{}).map(t=>({name:t.name,joinedAt:t.joinedAt,progress:t.progress,studentState:t.studentState}))},null,2)],{type:'application/json;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`버스수업-${k.code}-결과.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);}
function renderNotFound(){shell(`<main class="join-page"><section class="join-form solo"><p class="portal-kicker">수업 찾기</p><h1>이 수업을 찾을 수 없습니다.</h1><p>주소나 6자리 코드를 다시 확인해 주세요.</p><button class="portal-primary" data-nav="">처음으로</button></section></main>`,'portal-mode');}
async function showStandalone(){dispose();clearInterval(dashboardTimer);document.body.className='';app.innerHTML='';window.BUS_CLASSROOM=null;await import('./app.js');}
async function router(){dispose();dispose=()=>{};window.scrollTo(0,0);const parts=route();if(!parts.length)return renderLanding();if(parts[0]==='guide')return renderTeacherGuide();if(parts[0]==='teacher'&&parts[1])return mountTeacher(parts[1]);if(parts[0]==='join')return parts[1]?renderJoin(parts[1]):renderCodeEntry();if(parts[0]==='preview'&&parts[1])return startPreview(parts[1]);if(parts[0]==='print'&&parts[1]==='residents')return renderPrint();if(parts[0]==='play')return showStandalone();renderNotFound();}
window.addEventListener('hashchange',()=>location.reload());router();
